def levenshtein(a: str, b: str) -> int:
    prev = list(range(len(b) + 1))          # row 0: D[0][j] = j
    for i, ca in enumerate(a, start=1):
        cur = [i]                           # D[i][0] = i
        for j, cb in enumerate(b, start=1):
            cur.append(min(
                prev[j] + 1,                # delete ca
                cur[j - 1] + 1,             # insert cb
                prev[j - 1] + (ca != cb),   # match or substitute
            ))
        prev = cur
    return prev[-1]

print(levenshtein("kitten", "sitting"))  # 3

CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE INDEX words_trgm ON words USING GIN (w gin_trgm_ops);

-- filter with the index (% uses pg_trgm.similarity_threshold, default 0.3)
SELECT w, similarity(w, 'recieve') AS sml
FROM words
WHERE w % 'recieve'
ORDER BY sml DESC;

-- nearest neighbours by distance (1 - similarity): GiST supports this, GIN does not
CREATE INDEX words_trgm_gist ON words USING GIST (w gist_trgm_ops);
SELECT w, w <-> 'recieve' AS dist FROM words ORDER BY dist LIMIT 10;

q, k = "fuzzy", 1

def step(row, ch):
    new = [row[0] + 1]
    for j in range(1, len(q) + 1):
        new.append(min(row[j] + 1, new[j - 1] + 1,
                       row[j - 1] + (q[j - 1] != ch)))
    return new

def accepts(term):
    row = list(range(len(q) + 1))   # start state
    for ch in term:
        row = step(row, ch)
        if min(row) > k:
            return False            # dead state: prune
    return row[-1] <= k
